api.adaptor:
var items = payload.data || [];
function typeText(v) { var m = {'timeseries':'通用时序数据','vibration':'振动数据','temperature':'温度数据','plc-status':'PLC 状态数据','feature-data':'特征数据','anomaly-report':'异常报告','dataset':'数据集'}; return m[v] || v || '-'; }
function targetText(v) { if (v === 'local') return '保存到边缘云'; if (v === 'center') return '上传至中心云'; if (v === 'terminal') return '下发终端'; return v || '-'; }
function locationText(v) { if (!v) return '-'; if (v.indexOf('edge:') === 0) return '边缘云 ' + v.substring(5); if (v === 'center') return '中心云'; if (v === 'terminal') return '终端'; return v; }
function statusText(v) { if (!v) return '-'; if (v === '待处理' || v.indexOf('寰') === 0) return '待处理'; if (v === '处理中' || v.indexOf('澶勭悊涓') === 0) return '处理中'; if (v === '处理完成' || v.indexOf('澶勭悊瀹') === 0) return '处理完成'; if (v === '处理失败' || v.indexOf('澶勭悊澶') === 0) return '处理失败'; return v; }
items = items.map(function(item) { return {...item, executionLocationText: locationText(item.executionLocation), inputDataTypeText: typeText(item.inputDataType), outputDataTypeText: typeText(item.outputDataType), outputTargetText: targetText(item.outputTarget), processStatusText: statusText(item.processStatus)}; });
return {...payload, status: payload.status === 200 ? 0 : payload.status, msg: payload.message, data: {items: items}};
